// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _minSum) public {
        // Restrict to avoid overflow issues in the reference
        _minSum = bound(_minSum, 0, type(uint256).max / 2);
        // Step 1: Initialize contract and set MinSum if we want
        c.SetMinSum(_minSum);
        c.Initialized();
        // Record the MinSum after setup
        uint256 expectedMinSum = _minSum;
        // Step 2: Call Collect with a value that may or may not succeed
        // We need a valid sender with some balance to potentially pass the condition
        // For simplicity, fund the contract so that senders can call Collect
        // But to avoid revert complications, we just call Collect and assert MinSum unchanged
        // Use a random caller with some balance
        address sender = address(0x1234);
        vm.deal(sender, 1 ether);
        vm.prank(sender);
        (bool success,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", 0));
        // After call, MinSum must still equal expectedMinSum (the one set by SetMinSum)
        assertTrue(c.MinSum() == expectedMinSum);
    }
}

